return ['domain'=>'dosieci-ebay-connector','plural-forms'=>'nplurals=3; plural=(n == 1) ? 0 : ((n % 10 >= 2 && n % 10 <= 4 && (n % 100 < 12 || n % 100 > 14)) ? 1 : 2);','language'=>'pl_PL','project-id-version'=>'DoSieci eBay Connector 1.0.0','pot-creation-date'=>'2026-09-24T20:28:29+00:00','po-revision-date'=>'2026-09-24T20:28:29+00:00','messages'=>['DoSieci eBay Connector'=>'DoSieci eBay Connector','https://dosieci.pl/wtyczki/ebay-connector-woocommerce/'=>'https://dosieci.pl/wtyczki/ebay-connector-woocommerce/','Connect your site to eBay with your own eBay developer keys: test the connection and browse eBay listings from wp-admin. Read-only, Sandbox by default. Not affiliated with eBay Inc.'=>'Połączenie witryny z eBay na Twoich własnych kluczach deweloperskich eBay: test połączenia i przeglądanie ofert eBay z wp-admina. Wyłącznie do odczytu, domyślnie Sandbox. Wtyczka nie jest powiązana z eBay Inc.','DoSieci'=>'DoSieci','https://dosieci.pl/'=>'https://dosieci.pl/','eBay rejected the application keys. Check the App ID (Client ID) and Cert ID (Client Secret), and that they belong to the selected environment (Sandbox or Production).'=>'eBay odrzucił klucze aplikacji. Sprawdź App ID (Client ID) i Cert ID (Client Secret) oraz to, czy należą do wybranego środowiska (Sandbox lub Production).','eBay returned HTTP error %d while issuing the access token.'=>'eBay zwrócił błąd HTTP %d podczas wydawania tokenu dostępu.','eBay returned HTTP error %d.'=>'eBay zwrócił błąd HTTP %d.','(no title)'=>'(bez tytułu)','The eBay response contains no access token.'=>'Odpowiedź eBay nie zawiera tokenu dostępu.','eBay Connector'=>'eBay Connector','Settings'=>'Ustawienia','You do not have permission to do this.'=>'Nie masz uprawnień do wykonania tej operacji.','You do not have permission to access this page.'=>'Nie masz uprawnień do tej strony.','Settings saved.'=>'Zapisano ustawienia.','Read-only: tests the connection to eBay and browses listings. It does not publish listings, import orders or change stock levels.'=>'Wyłącznie do odczytu: sprawdza połączenie z eBay i przegląda oferty. Nie wystawia ofert, nie importuje zamówień i nie zmienia stanów magazynowych.','Requests go from this site straight to eBay with your own application keys, never through DoSieci.'=>'Zapytania idą z tej witryny bezpośrednio do eBay na Twoich kluczach aplikacji, nigdy przez DoSieci.','The Production environment is active.'=>'Aktywne jest środowisko produkcyjne.','Requests go to the live eBay.'=>'Zapytania trafiają do prawdziwego eBay.','eBay application keys'=>'Klucze aplikacji eBay','Create a keyset in the eBay Developers Program (developer.ebay.com) and paste it here. Sandbox and Production have separate keysets.'=>'Utwórz zestaw kluczy w eBay Developers Program (developer.ebay.com) i wklej go tutaj. Sandbox i Production mają osobne zestawy kluczy.','App ID (Client ID)'=>'App ID (Client ID)','Cert ID (Client Secret)'=>'Cert ID (Client Secret)','Leave empty to keep the saved secret.'=>'Zostaw puste, aby zachować zapisany sekret.','Environment'=>'Środowisko','Sandbox (default)'=>'Sandbox (domyślnie)','Production'=>'Production','Marketplace'=>'Serwis eBay','The eBay site searched, which also decides the currency of the prices.'=>'Przeszukiwany serwis eBay — od niego zależy też waluta cen.','Save'=>'Zapisz','Browse listings (read-only)'=>'Przeglądaj oferty (tylko odczyt)','Search eBay'=>'Szukaj w eBay','for example: hiking boots'=>'np. buty trekkingowe','An administrator needs to enter the eBay application keys first.'=>'Najpierw administrator musi wprowadzić klucze aplikacji eBay.','About %1$d listing found on %2$s.'=>'Znaleziono około %1$d oferty w %2$s.' . "\0" . 'Znaleziono około %1$d ofert w %2$s.' . "\0" . 'Znaleziono około %1$d ofert w %2$s.','Listing'=>'Oferta','Price'=>'Cena','Condition'=>'Stan','Seller'=>'Sprzedawca','No results.'=>'Brak wyników.']];